import os
from typing import Any, Dict, List, Optional

import boto3


def _text_from_field(field: Any) -> Optional[str]:
    if field is None:
        return None
    if isinstance(field, str):
        return field.strip() or None
    if isinstance(field, dict):
        for key in ("ValueDetection", "Text", "Value", "content", "Content", "DetectedText"):
            val = field.get(key)
            if isinstance(val, str) and val.strip():
                return val.strip()
        if "Text" in field and isinstance(field["Text"], dict):
            nested = _text_from_field(field["Text"])
            if nested:
                return nested
    return None


def _num_from_field(field: Any) -> Optional[float]:
    txt = _text_from_field(field)
    if txt is None:
        return None
    cleaned = txt.replace(",", "").replace("$", "").replace("€", "").replace("£", "").strip()
    try:
        return float(cleaned)
    except ValueError:
        return None


def _extract_key_map(expense_doc: Dict[str, Any]) -> Dict[str, Any]:
    result = {}
    for kv in expense_doc.get("SummaryFields", []) or []:
        key = _text_from_field(kv.get("Type", {})) or _text_from_field(kv.get("LabelDetection", {})) or _text_from_field(kv.get("Label"))
        if not key:
            continue
        key_lower = key.lower()
        result[key_lower] = kv
    return result


def extract_receipt(image_path: str) -> Dict[str, Any]:
    textract = boto3.client("textract")
    with open(image_path, "rb") as f:
        payload = f.read()

    response = textract.analyze_expense(Document={"Bytes": payload})
    expense_docs = response.get("ExpenseDocuments", []) or []

    merchant = None
    tax = None
    total = None
    items: List[Dict[str, Any]] = []

    if expense_docs:
        doc = expense_docs[0]
        key_map = _extract_key_map(doc)

        for candidate in ("merchant", "seller", "vendor", "store", "business name", "company"):
            if candidate in key_map:
                merchant = _text_from_field(key_map[candidate].get("ValueDetection"))
                if merchant:
                    break

        for candidate in ("tax", "tax amount", "sales tax", "vat", "gst"):
            if candidate in key_map:
                tax = _num_from_field(key_map[candidate].get("ValueDetection"))
                if tax is not None:
                    break

        for candidate in ("total", "amount due", "grand total", "invoice total", "total amount"):
            if candidate in key_map:
                total = _num_from_field(key_map[candidate].get("ValueDetection"))
                if total is not None:
                    break

        for line_item_group in doc.get("LineItemGroups", []) or []:
            for line_item in line_item_group.get("LineItems", []) or []:
                item: Dict[str, Any] = {}
                for exp in line_item.get("LineItemExpenseFields", []) or []:
                    field_type = _text_from_field(exp.get("Type", {}))
                    value = exp.get("ValueDetection", {})
                    if not field_type:
                        continue
                    k = field_type.lower()
                    if k in ("item", "description", "product", "name"):
                        item["description"] = _text_from_field(value)
                    elif k in ("quantity", "qty"):
                        qty = _num_from_field(value)
                        if qty is not None:
                            item["quantity"] = qty
                    elif k in ("unit price", "unitprice", "price", "rate"):
                        unit_price = _num_from_field(value)
                        if unit_price is not None:
                            item["unit_price"] = unit_price
                    elif k in ("amount", "line total", "total"):
                        amount = _num_from_field(value)
                        if amount is not None:
                            item["amount"] = amount
                if item:
                    items.append(item)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
